def maximum_removable_stones(stones):
 parent={}
 def find(x):
  parent.setdefault(x,x)
  if parent[x]!=x:parent[x]=find(parent[x])
  return parent[x]
 for r,c in stones:
  a,b=find(('r',r)),find(('c',c));parent[a]=b
 return len(stones)-len({find(('r',r)) for r,c in stones})

